mapper.select:
SELECT avg_price
FROM apt_pyung_stats
WHERE apt_seq = #{aptSeq}
  AND pyung = #{pyung}

SELECT COUNT(*) > 0
FROM apt_pyung_stats
WHERE apt_seq = #{aptSeq}
  AND pyung = #{pyung}

SELECT hd.deal_date AS transactionDate, hd.pyung AS pyungType, hd.deal_amount AS dealAmount, hd.floor AS floor, hd.apt_dong AS aptDong FROM housedeals hd WHERE hd.apt_seq = #{aptSeq}
AND hd.pyung = #{pyung}
ORDER BY hd.deal_date DESC LIMIT #{limit}

SELECT DATE_FORMAT(STR_TO_DATE(CAST(deal_date AS CHAR), '%Y%m%d'), '%Y-%m') AS month, ROUND(AVG(deal_amount)) AS avgPrice, COUNT(*) AS transactionCount FROM housedeals WHERE apt_seq = #{aptSeq}
AND pyung = #{pyung}
AND deal_date >= CAST(CONCAT(#{startMonth}, '01') AS UNSIGNED) AND deal_date <= CAST(CONCAT(#{endMonth}, '31') AS UNSIGNED) GROUP BY DATE_FORMAT(STR_TO_DATE(CAST(deal_date AS CHAR), '%Y%m%d'), '%Y-%m') ORDER BY month

SELECT ROUND(AVG(deal_amount)) AS avgPrice
FROM housedeals
WHERE apt_seq = #{aptSeq}

    AND pyung = #{pyung}

AND DATE_FORMAT(deal_date, '%Y-%m') = (
    SELECT DATE_FORMAT(deal_date, '%Y-%m')
    FROM housedeals
    WHERE apt_seq = #{aptSeq}

        AND pyung = #{pyung}

    AND deal_date < CAST(CONCAT(#{beforeMonth}, '01') AS UNSIGNED)
    ORDER BY deal_date DESC
    LIMIT 1
)
